lab.solution:
class Progress:
    def __init__(self, percent=0):
        self.percent = percent

    @property
    def percent(self):
        return self._percent

    @percent.setter
    def percent(self, value):
        if type(value) is not int or not 0 <= value <= 100:
            raise ValueError('percent must be an integer from 0 to 100')
        self._percent = value

    def __repr__(self):
        return f'Progress(percent={self.percent})'

for valid in (0, 100):
    print(Progress(valid))
for invalid in (-1, 101, True):
    try:
        Progress(invalid)
    except ValueError:
        print('rejected', repr(invalid))
